-- Ticarti v29 Shopify-readiness domains
CREATE TABLE IF NOT EXISTS "DraftOrder" ("id" TEXT PRIMARY KEY,"storeId" TEXT NOT NULL,"customerId" TEXT,"status" TEXT NOT NULL DEFAULT 'DRAFT',"currency" TEXT NOT NULL DEFAULT 'TRY',"lineItems" JSONB NOT NULL,"shippingAddress" JSONB,"billingAddress" JSONB,"subtotal" DECIMAL(18,2) NOT NULL DEFAULT 0,"discountTotal" DECIMAL(18,2) NOT NULL DEFAULT 0,"taxTotal" DECIMAL(18,2) NOT NULL DEFAULT 0,"shippingTotal" DECIMAL(18,2) NOT NULL DEFAULT 0,"total" DECIMAL(18,2) NOT NULL DEFAULT 0,"note" TEXT,"tags" TEXT[] NOT NULL DEFAULT ARRAY[]::TEXT[],"completedOrderId" TEXT,"createdBy" TEXT,"expiresAt" TIMESTAMP(3),"metadata" JSONB,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "DraftOrder_storeId_fkey" FOREIGN KEY ("storeId") REFERENCES "Tenant"("id") ON DELETE CASCADE);
CREATE INDEX IF NOT EXISTS "DraftOrder_storeId_status_createdAt_idx" ON "DraftOrder"("storeId","status","createdAt");
CREATE TABLE IF NOT EXISTS "GiftCard" ("id" TEXT PRIMARY KEY,"storeId" TEXT NOT NULL,"codeHash" TEXT NOT NULL,"lastFour" TEXT NOT NULL,"customerId" TEXT,"status" TEXT NOT NULL DEFAULT 'ACTIVE',"currency" TEXT NOT NULL DEFAULT 'TRY',"initialBalance" DECIMAL(18,2) NOT NULL,"balance" DECIMAL(18,2) NOT NULL,"expiresAt" TIMESTAMP(3),"note" TEXT,"metadata" JSONB,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "GiftCard_storeId_fkey" FOREIGN KEY ("storeId") REFERENCES "Tenant"("id") ON DELETE CASCADE,CONSTRAINT "GiftCard_storeId_codeHash_key" UNIQUE("storeId","codeHash"));
CREATE INDEX IF NOT EXISTS "GiftCard_storeId_status_expiresAt_idx" ON "GiftCard"("storeId","status","expiresAt");
CREATE TABLE IF NOT EXISTS "StoreCreditAccount" ("id" TEXT PRIMARY KEY,"storeId" TEXT NOT NULL,"customerId" TEXT NOT NULL,"currency" TEXT NOT NULL DEFAULT 'TRY',"balance" DECIMAL(18,2) NOT NULL DEFAULT 0,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "StoreCreditAccount_storeId_fkey" FOREIGN KEY ("storeId") REFERENCES "Tenant"("id") ON DELETE CASCADE,CONSTRAINT "StoreCreditAccount_storeId_customerId_currency_key" UNIQUE("storeId","customerId","currency"));
CREATE TABLE IF NOT EXISTS "StoreCreditTransaction" ("id" TEXT PRIMARY KEY,"accountId" TEXT NOT NULL,"type" TEXT NOT NULL,"amount" DECIMAL(18,2) NOT NULL,"balanceAfter" DECIMAL(18,2) NOT NULL,"referenceType" TEXT,"referenceId" TEXT,"note" TEXT,"createdBy" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "StoreCreditTransaction_accountId_fkey" FOREIGN KEY ("accountId") REFERENCES "StoreCreditAccount"("id") ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS "ExchangeRequest" ("id" TEXT PRIMARY KEY,"storeId" TEXT NOT NULL,"orderId" TEXT NOT NULL,"returnRequestId" TEXT,"customerId" TEXT,"status" TEXT NOT NULL DEFAULT 'REQUESTED',"returnItems" JSONB NOT NULL,"replacementItems" JSONB NOT NULL,"differenceAmount" DECIMAL(18,2) NOT NULL DEFAULT 0,"currency" TEXT NOT NULL DEFAULT 'TRY',"paymentStatus" TEXT NOT NULL DEFAULT 'PENDING',"note" TEXT,"metadata" JSONB,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "ExchangeRequest_storeId_fkey" FOREIGN KEY ("storeId") REFERENCES "Tenant"("id") ON DELETE CASCADE);
CREATE INDEX IF NOT EXISTS "ExchangeRequest_storeId_status_createdAt_idx" ON "ExchangeRequest"("storeId","status","createdAt");
CREATE TABLE IF NOT EXISTS "AbandonedCheckout" ("id" TEXT PRIMARY KEY,"storeId" TEXT NOT NULL,"cartId" TEXT NOT NULL,"customerId" TEXT,"email" TEXT,"phone" TEXT,"status" TEXT NOT NULL DEFAULT 'OPEN',"currency" TEXT NOT NULL DEFAULT 'TRY',"total" DECIMAL(18,2) NOT NULL DEFAULT 0,"snapshot" JSONB NOT NULL,"recoveryTokenHash" TEXT UNIQUE,"recoveredOrderId" TEXT,"lastActivityAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"recoveredAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "AbandonedCheckout_storeId_fkey" FOREIGN KEY ("storeId") REFERENCES "Tenant"("id") ON DELETE CASCADE,CONSTRAINT "AbandonedCheckout_storeId_cartId_key" UNIQUE("storeId","cartId"));
CREATE INDEX IF NOT EXISTS "AbandonedCheckout_storeId_status_lastActivityAt_idx" ON "AbandonedCheckout"("storeId","status","lastActivityAt");
CREATE TABLE IF NOT EXISTS "FraudRule" ("id" TEXT PRIMARY KEY,"storeId" TEXT NOT NULL,"name" TEXT NOT NULL,"enabled" BOOLEAN NOT NULL DEFAULT TRUE,"priority" INTEGER NOT NULL DEFAULT 100,"conditions" JSONB NOT NULL,"actions" JSONB NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "FraudRule_storeId_fkey" FOREIGN KEY ("storeId") REFERENCES "Tenant"("id") ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS "OrderRiskAssessment" ("id" TEXT PRIMARY KEY,"storeId" TEXT NOT NULL,"orderId" TEXT NOT NULL,"score" INTEGER NOT NULL DEFAULT 0,"level" TEXT NOT NULL DEFAULT 'LOW',"signals" JSONB NOT NULL,"decision" TEXT NOT NULL DEFAULT 'ALLOW',"reviewedBy" TEXT,"reviewedAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "OrderRiskAssessment_storeId_fkey" FOREIGN KEY ("storeId") REFERENCES "Tenant"("id") ON DELETE CASCADE,CONSTRAINT "OrderRiskAssessment_storeId_orderId_key" UNIQUE("storeId","orderId"));
CREATE TABLE IF NOT EXISTS "CommerceMarket" ("id" TEXT PRIMARY KEY,"storeId" TEXT NOT NULL,"name" TEXT NOT NULL,"handle" TEXT NOT NULL,"active" BOOLEAN NOT NULL DEFAULT TRUE,"countries" TEXT[] NOT NULL DEFAULT ARRAY[]::TEXT[],"currencies" TEXT[] NOT NULL DEFAULT ARRAY[]::TEXT[],"locales" TEXT[] NOT NULL DEFAULT ARRAY[]::TEXT[],"domains" JSONB,"settings" JSONB,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "CommerceMarket_storeId_fkey" FOREIGN KEY ("storeId") REFERENCES "Tenant"("id") ON DELETE CASCADE,CONSTRAINT "CommerceMarket_storeId_handle_key" UNIQUE("storeId","handle"));
CREATE TABLE IF NOT EXISTS "PriceList" ("id" TEXT PRIMARY KEY,"storeId" TEXT NOT NULL,"marketId" TEXT,"customerGroupId" TEXT,"name" TEXT NOT NULL,"currency" TEXT NOT NULL,"priority" INTEGER NOT NULL DEFAULT 100,"active" BOOLEAN NOT NULL DEFAULT TRUE,"rules" JSONB,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "PriceList_storeId_fkey" FOREIGN KEY ("storeId") REFERENCES "Tenant"("id") ON DELETE CASCADE,CONSTRAINT "PriceList_marketId_fkey" FOREIGN KEY ("marketId") REFERENCES "CommerceMarket"("id") ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS "PriceListPrice" ("id" TEXT PRIMARY KEY,"priceListId" TEXT NOT NULL,"variantId" TEXT NOT NULL,"price" DECIMAL(18,2) NOT NULL,"compareAtPrice" DECIMAL(18,2),"minQuantity" INTEGER NOT NULL DEFAULT 1,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "PriceListPrice_priceListId_fkey" FOREIGN KEY ("priceListId") REFERENCES "PriceList"("id") ON DELETE CASCADE,CONSTRAINT "PriceListPrice_priceListId_variantId_minQuantity_key" UNIQUE("priceListId","variantId","minQuantity"));
CREATE TABLE IF NOT EXISTS "B2BCompany" ("id" TEXT PRIMARY KEY,"storeId" TEXT NOT NULL,"name" TEXT NOT NULL,"externalRef" TEXT,"taxNumber" TEXT,"status" TEXT NOT NULL DEFAULT 'ACTIVE',"defaultPriceListId" TEXT,"paymentTermsDays" INTEGER NOT NULL DEFAULT 0,"creditLimit" DECIMAL(18,2),"currency" TEXT NOT NULL DEFAULT 'TRY',"metadata" JSONB,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "B2BCompany_storeId_fkey" FOREIGN KEY ("storeId") REFERENCES "Tenant"("id") ON DELETE CASCADE);
CREATE UNIQUE INDEX IF NOT EXISTS "B2BCompany_storeId_externalRef_key" ON "B2BCompany"("storeId","externalRef");
CREATE TABLE IF NOT EXISTS "B2BCompanyLocation" ("id" TEXT PRIMARY KEY,"companyId" TEXT NOT NULL,"name" TEXT NOT NULL,"address" JSONB NOT NULL,"taxNumber" TEXT,"taxOffice" TEXT,"paymentTermsDays" INTEGER,"priceListId" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "B2BCompanyLocation_companyId_fkey" FOREIGN KEY ("companyId") REFERENCES "B2BCompany"("id") ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS "B2BBuyer" ("id" TEXT PRIMARY KEY,"companyId" TEXT NOT NULL,"customerId" TEXT NOT NULL,"role" TEXT NOT NULL DEFAULT 'BUYER',"permissions" TEXT[] NOT NULL DEFAULT ARRAY[]::TEXT[],"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "B2BBuyer_companyId_fkey" FOREIGN KEY ("companyId") REFERENCES "B2BCompany"("id") ON DELETE CASCADE,CONSTRAINT "B2BBuyer_companyId_customerId_key" UNIQUE("companyId","customerId"));
CREATE TABLE IF NOT EXISTS "PurchaseOrder" ("id" TEXT PRIMARY KEY,"storeId" TEXT NOT NULL,"supplierId" TEXT,"warehouseId" TEXT,"number" TEXT NOT NULL,"status" TEXT NOT NULL DEFAULT 'DRAFT',"currency" TEXT NOT NULL DEFAULT 'TRY',"lineItems" JSONB NOT NULL,"subtotal" DECIMAL(18,2) NOT NULL DEFAULT 0,"taxTotal" DECIMAL(18,2) NOT NULL DEFAULT 0,"total" DECIMAL(18,2) NOT NULL DEFAULT 0,"expectedAt" TIMESTAMP(3),"receivedAt" TIMESTAMP(3),"note" TEXT,"metadata" JSONB,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "PurchaseOrder_storeId_fkey" FOREIGN KEY ("storeId") REFERENCES "Tenant"("id") ON DELETE CASCADE,CONSTRAINT "PurchaseOrder_storeId_number_key" UNIQUE("storeId","number"));
CREATE TABLE IF NOT EXISTS "ShippingProfile" ("id" TEXT PRIMARY KEY,"storeId" TEXT NOT NULL,"name" TEXT NOT NULL,"active" BOOLEAN NOT NULL DEFAULT TRUE,"productIds" TEXT[] NOT NULL DEFAULT ARRAY[]::TEXT[],"zones" JSONB NOT NULL,"rateRules" JSONB NOT NULL,"settings" JSONB,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "ShippingProfile_storeId_fkey" FOREIGN KEY ("storeId") REFERENCES "Tenant"("id") ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS "MetaobjectDefinition" ("id" TEXT PRIMARY KEY,"storeId" TEXT NOT NULL,"type" TEXT NOT NULL,"name" TEXT NOT NULL,"description" TEXT,"fields" JSONB NOT NULL,"access" JSONB,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "MetaobjectDefinition_storeId_fkey" FOREIGN KEY ("storeId") REFERENCES "Tenant"("id") ON DELETE CASCADE,CONSTRAINT "MetaobjectDefinition_storeId_type_key" UNIQUE("storeId","type"));
CREATE TABLE IF NOT EXISTS "MetaobjectEntry" ("id" TEXT PRIMARY KEY,"definitionId" TEXT NOT NULL,"handle" TEXT NOT NULL,"fields" JSONB NOT NULL,"status" TEXT NOT NULL DEFAULT 'ACTIVE',"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "MetaobjectEntry_definitionId_fkey" FOREIGN KEY ("definitionId") REFERENCES "MetaobjectDefinition"("id") ON DELETE CASCADE,CONSTRAINT "MetaobjectEntry_definitionId_handle_key" UNIQUE("definitionId","handle"));
CREATE TABLE IF NOT EXISTS "SalesChannel" ("id" TEXT PRIMARY KEY,"storeId" TEXT NOT NULL,"name" TEXT NOT NULL,"type" TEXT NOT NULL,"active" BOOLEAN NOT NULL DEFAULT TRUE,"config" JSONB,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "SalesChannel_storeId_fkey" FOREIGN KEY ("storeId") REFERENCES "Tenant"("id") ON DELETE CASCADE,CONSTRAINT "SalesChannel_storeId_type_name_key" UNIQUE("storeId","type","name"));
CREATE TABLE IF NOT EXISTS "ChannelPublication" ("id" TEXT PRIMARY KEY,"channelId" TEXT NOT NULL,"resourceType" TEXT NOT NULL,"resourceId" TEXT NOT NULL,"status" TEXT NOT NULL DEFAULT 'PUBLISHED',"externalId" TEXT,"metadata" JSONB,"publishedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "ChannelPublication_channelId_fkey" FOREIGN KEY ("channelId") REFERENCES "SalesChannel"("id") ON DELETE CASCADE,CONSTRAINT "ChannelPublication_channelId_resourceType_resourceId_key" UNIQUE("channelId","resourceType","resourceId"));
